async function naverAccess(force=false){if(sharedSettings.enabled){if(force)await naverRequest({action:'token'});return 'server-managed';}const values={clientId:$('naver-client').value.trim(),clientSecret:$('naver-secret').value.trim(),accountId:$('naver-account').value.trim()},binding=JSON.stringify(values);if(force||!naverToken||naverBinding!==binding||naverToken.until<Date.now()){const token=await naverRequest({action:'token',...values});if(!token.access_token)throw Error('네이버 접근 토큰이 없습니다.');naverToken={value:token.access_token,until:Date.now()+(Number(token.expires_in)||3600)*1000-60000};naverBinding=binding;}return naverToken.value;}
