const revenueApp=initializeRevenueCheck({today,getVendor:()=>$('vendor').value.trim(),notice,fetchData:async({from,to,ordersFrom,onProgress})=>{
 if(busy)throw Error('다른 조회가 진행 중입니다.');if(!credentialsReady({market:true}))throw Error('쿠팡 API 인증 정보를 먼저 입력하세요.');setBusy(true);try{const vendor=requestContext.vendor,data=await fetchRevenue(api,{vendor,from,to,onProgress});let actualFrom=ordersFrom;for(const record of data.records){const date=paymentDate(record.saleDate);if(date&&date<actualFrom)actualFrom=date;}onProgress('구매확정 주문 대사 · 주문 검색 '+actualFrom+' ~ '+to);await ensureShared(vendor,actualFrom,to,{market:true,rocket:false,naver:false});return {...data,orders:rows,vendor,ordersFrom:actualFrom};}finally{setBusy(false)}
}});
